cbz w11,3f
cbnz x21,1b
mov x16,#SYS_thread_selfid
svc #0x80
str x0,[x20]
mov x21,#1
b 1b
3:
ldp x21,x30,[sp,#16]
ldp x19,x20,[sp],#32
ret

